-- Phase 4B: authenticated, versioned and idempotent artist workflow boundary.
-- Receipts older than 90 days may be deleted only after their referenced audit and
-- communication records have passed the game's retention window.
ALTER TABLE public.festival_artist_plan_requests ADD COLUMN IF NOT EXISTS target_entity_type text;
ALTER TABLE public.festival_artist_plan_requests ADD COLUMN IF NOT EXISTS completed_at timestamptz;
CREATE INDEX IF NOT EXISTS festival_artist_request_cleanup_idx ON public.festival_artist_plan_requests(completed_at) WHERE status='succeeded';

CREATE TABLE public.festival_artist_communications (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.festival_artist_plan_requests(id) ON DELETE RESTRICT,
 recipient_profile_id uuid NOT NULL REFERENCES public.profiles(id), channel text NOT NULL CHECK(channel IN ('mail','notification')),
 event_type text NOT NULL, title text NOT NULL, body text NOT NULL, action_path text NOT NULL DEFAULT '/festival-opportunities', created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(request_id,recipient_profile_id,channel,event_type)
);
ALTER TABLE public.festival_artist_communications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.festival_artist_communications FROM PUBLIC,anon,authenticated;

CREATE OR REPLACE FUNCTION public._festival_artist_authorised(p_profile uuid,p_type text,p_artist_profile uuid,p_band uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT CASE WHEN p_type='solo' THEN p_artist_profile=p_profile WHEN p_type='band' THEN EXISTS(
  SELECT 1 FROM public.band_members bm WHERE bm.band_id=p_band AND bm.profile_id=p_profile
   AND coalesce(bm.member_status,'active')='active' AND lower(coalesce(bm.role,'')) IN ('leader','founder','co-leader','manager')) ELSE false END
$$;
CREATE OR REPLACE FUNCTION public._festival_artist_begin(p_company uuid,p_action text,p_target_type text,p_target uuid,p_key uuid,p_payload jsonb)
RETURNS public.festival_artist_plan_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE a uuid:=public._caller_profile_id(); r public.festival_artist_plan_requests%ROWTYPE; h text:=encode(digest(p_payload::text,'sha256'),'hex');
BEGIN IF auth.uid() IS NULL OR a IS NULL OR p_key IS NULL THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(a::text||p_action||p_key::text,0));
 SELECT * INTO r FROM public.festival_artist_plan_requests WHERE caller_profile_id=a AND action=p_action AND idempotency_key=p_key AND target_entity_id IS NOT DISTINCT FROM p_target;
 IF FOUND THEN IF r.payload_hash<>h THEN RAISE EXCEPTION 'festival_artist_idempotency_conflict' USING ERRCODE='P0001'; END IF; RETURN r; END IF;
 INSERT INTO public.festival_artist_plan_requests(festival_company_id,caller_profile_id,target_entity_id,target_entity_type,action,idempotency_key,payload_hash)
 VALUES(p_company,a,p_target,p_target_type,p_action,p_key,h) RETURNING * INTO r; RETURN r;
END $$;
CREATE OR REPLACE FUNCTION public._festival_artist_finish(p_request uuid,p_result jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN UPDATE public.festival_artist_plan_requests SET status='succeeded',result=p_result,completed_at=now() WHERE id=p_request; RETURN p_result; END $$;
CREATE OR REPLACE FUNCTION public._festival_artist_audit(p_company uuid,p_actor uuid,p_type text,p_id uuid,p_event text,p_old text,p_new text,p_version int) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 INSERT INTO public.festival_artist_plan_audit(festival_company_id,actor_profile_id,entity_type,entity_id,event_type,previous_state,new_state,version) VALUES(p_company,p_actor,p_type,p_id,p_event,p_old,p_new,p_version) $$;
CREATE OR REPLACE FUNCTION public._festival_artist_notify(p_request uuid,p_recipient uuid,p_event text,p_title text,p_body text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$
 INSERT INTO public.festival_artist_communications(request_id,recipient_profile_id,channel,event_type,title,body)
 SELECT p_request,p_recipient,c,p_event,p_title,p_body FROM unnest(ARRAY['mail','notification']) c ON CONFLICT DO NOTHING $$;

CREATE OR REPLACE FUNCTION public.submit_festival_artist_application(p_festival_company_id uuid,p_application_window_id uuid,p_artist_type text,p_artist_profile_id uuid DEFAULT NULL,p_band_id uuid DEFAULT NULL,p_preferred_dates date[] DEFAULT '{}',p_preferred_stage_types text[] DEFAULT '{}',p_minimum_fee_minor bigint DEFAULT 0,p_requested_fee_minor bigint DEFAULT 0,p_minimum_set_minutes integer DEFAULT 30,p_maximum_set_minutes integer DEFAULT 60,p_message text DEFAULT NULL,p_idempotency_key uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); w public.festival_artist_application_windows%ROWTYPE; pr public.festival_artist_programmes%ROWTYPE; app public.festival_artist_applications%ROWTYPE; req public.festival_artist_plan_requests%ROWTYPE; payload jsonb; BEGIN
 SELECT * INTO w FROM public.festival_artist_application_windows WHERE id=p_application_window_id; SELECT * INTO pr FROM public.festival_artist_programmes WHERE id=w.festival_artist_programme_id AND festival_company_id=p_festival_company_id;
 IF NOT FOUND OR NOT w.active OR now() NOT BETWEEN w.opens_at AND w.closes_at OR pr.application_mode NOT IN ('applications_only','hybrid') THEN RAISE EXCEPTION 'festival_artist_applications_closed' USING ERRCODE='P0001'; END IF;
 IF NOT public._festival_artist_authorised(a,p_artist_type,p_artist_profile_id,p_band_id) THEN RAISE EXCEPTION 'festival_artist_application_forbidden' USING ERRCODE='P0001'; END IF;
 IF p_minimum_fee_minor<0 OR p_requested_fee_minor<p_minimum_fee_minor OR p_minimum_set_minutes<10 OR p_maximum_set_minutes<p_minimum_set_minutes OR (w.maximum_set_minutes IS NOT NULL AND p_maximum_set_minutes>w.maximum_set_minutes) THEN RAISE EXCEPTION 'festival_artist_not_eligible' USING ERRCODE='P0001'; END IF;
 payload:=jsonb_build_object('window',p_application_window_id,'type',p_artist_type,'profile',p_artist_profile_id,'band',p_band_id,'dates',p_preferred_dates,'stages',p_preferred_stage_types,'minimumFee',p_minimum_fee_minor,'requestedFee',p_requested_fee_minor,'minimumSet',p_minimum_set_minutes,'maximumSet',p_maximum_set_minutes,'message',p_message);
 req:=public._festival_artist_begin(p_festival_company_id,'submit_application','application',p_application_window_id,p_idempotency_key,payload); IF req.status='succeeded' THEN RETURN req.result; END IF;
 BEGIN INSERT INTO public.festival_artist_applications(festival_artist_programme_id,application_window_id,artist_type,artist_profile_id,band_id,submitted_by_profile_id,preferred_dates,preferred_stage_types,minimum_fee_minor,requested_fee_minor,minimum_set_minutes,maximum_set_minutes,fame_snapshot,popularity_snapshot,availability_snapshot,message)
 VALUES(pr.id,w.id,p_artist_type,p_artist_profile_id,p_band_id,a,p_preferred_dates,p_preferred_stage_types,p_minimum_fee_minor,p_requested_fee_minor,p_minimum_set_minutes,p_maximum_set_minutes,coalesce((SELECT fame FROM public.profiles WHERE id=p_artist_profile_id),0),0,jsonb_build_object('state','unknown','capturedAt',now()),nullif(btrim(p_message),'')) RETURNING * INTO app; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'festival_artist_application_duplicate' USING ERRCODE='P0001'; END;
 PERFORM public._festival_artist_audit(p_festival_company_id,a,'application',app.id,'application_submitted',NULL,'submitted',1); PERFORM public._festival_artist_notify(req.id,a,'application_submitted','Festival application submitted','Your application was delivered to Festival management.'); RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','application','application',to_jsonb(app)));
END $$;

CREATE OR REPLACE FUNCTION public.withdraw_festival_artist_application(p_application_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); x public.festival_artist_applications%ROWTYPE; c uuid; req public.festival_artist_plan_requests%ROWTYPE; BEGIN SELECT ap.* INTO x FROM public.festival_artist_applications ap JOIN public.festival_artist_programmes pr ON pr.id=ap.festival_artist_programme_id WHERE ap.id=p_application_id FOR UPDATE; SELECT festival_company_id INTO c FROM public.festival_artist_programmes WHERE id=x.festival_artist_programme_id; req:=public._festival_artist_begin(c,'withdraw_application','application',x.id,p_idempotency_key,jsonb_build_object('version',p_expected_version)); IF req.status='succeeded' THEN RETURN req.result; END IF; IF NOT public._festival_artist_authorised(a,x.artist_type,x.artist_profile_id,x.band_id) THEN RAISE EXCEPTION 'festival_artist_application_forbidden' USING ERRCODE='P0001'; END IF; IF x.version<>p_expected_version THEN RAISE EXCEPTION 'festival_artist_offer_stale' USING ERRCODE='P0001'; END IF; IF x.status NOT IN ('submitted','under_review','shortlisted','offer_pending') OR EXISTS(SELECT 1 FROM public.festival_artist_offers o WHERE o.application_id=x.id AND o.status IN ('sent','countered','accepted')) THEN RAISE EXCEPTION 'festival_artist_application_invalid_transition' USING ERRCODE='P0001'; END IF; UPDATE public.festival_artist_applications SET status='withdrawn',withdrawn_at=now(),updated_at=now(),version=version+1 WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_artist_audit(c,a,'application',x.id,'application_withdrawn',x.status,'withdrawn',x.version); RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','application','application',to_jsonb(x))); END $$;

CREATE OR REPLACE FUNCTION public.review_festival_artist_application(p_festival_company_id uuid,p_application_id uuid,p_expected_version integer,p_decision text,p_internal_notes text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); x public.festival_artist_applications%ROWTYPE; ns text; req public.festival_artist_plan_requests%ROWTYPE; BEGIN IF NOT public._festival_artist_manager(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; req:=public._festival_artist_begin(p_festival_company_id,'review_application','application',p_application_id,p_idempotency_key,jsonb_build_object('version',p_expected_version,'decision',p_decision,'notes',p_internal_notes)); IF req.status='succeeded' THEN RETURN req.result; END IF; SELECT ap.* INTO x FROM public.festival_artist_applications ap JOIN public.festival_artist_programmes pr ON pr.id=ap.festival_artist_programme_id WHERE ap.id=p_application_id AND pr.festival_company_id=p_festival_company_id FOR UPDATE; IF x.version<>p_expected_version THEN RAISE EXCEPTION 'festival_artist_offer_stale' USING ERRCODE='P0001'; END IF; ns:=CASE p_decision WHEN 'mark_under_review' THEN 'under_review' WHEN 'shortlist' THEN 'shortlisted' WHEN 'reject' THEN 'rejected' WHEN 'create_offer' THEN 'offer_pending' END; IF ns IS NULL OR (x.status,ns) NOT IN (('submitted','under_review'),('submitted','shortlisted'),('under_review','shortlisted'),('submitted','rejected'),('under_review','rejected'),('shortlisted','offer_pending')) THEN RAISE EXCEPTION 'festival_artist_application_invalid_transition' USING ERRCODE='P0001'; END IF; UPDATE public.festival_artist_applications SET status=ns,reviewed_at=now(),updated_at=now(),version=version+1 WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_artist_audit(p_festival_company_id,a,'application',x.id,'application_'||ns,NULL,ns,x.version); IF x.artist_profile_id IS NOT NULL THEN PERFORM public._festival_artist_notify(req.id,x.artist_profile_id,'application_'||ns,'Festival application update','Your Festival application status changed to '||replace(ns,'_',' ')||'.'); END IF; RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','application','application',to_jsonb(x))); END $$;
CREATE OR REPLACE FUNCTION public.send_festival_artist_invitation(p_festival_company_id uuid,p_artist_type text,p_artist_profile_id uuid,p_band_id uuid,p_suggested_fee_minor bigint,p_suggested_set_minutes integer,p_suggested_dates date[],p_suggested_stage_types text[],p_response_deadline timestamptz,p_message text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); pr public.festival_artist_programmes%ROWTYPE; x public.festival_artist_invitations%ROWTYPE; req public.festival_artist_plan_requests%ROWTYPE; BEGIN IF NOT public._festival_artist_manager(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; SELECT * INTO pr FROM public.festival_artist_programmes WHERE festival_company_id=p_festival_company_id; IF p_suggested_fee_minor<0 OR p_suggested_set_minutes NOT BETWEEN 10 AND 240 OR p_response_deadline<=now() THEN RAISE EXCEPTION 'festival_artist_invitation_invalid' USING ERRCODE='P0001'; END IF; req:=public._festival_artist_begin(p_festival_company_id,'send_invitation','invitation',coalesce(p_artist_profile_id,p_band_id),p_idempotency_key,jsonb_build_object('type',p_artist_type,'profile',p_artist_profile_id,'band',p_band_id,'fee',p_suggested_fee_minor,'set',p_suggested_set_minutes,'dates',p_suggested_dates,'stages',p_suggested_stage_types,'deadline',p_response_deadline,'message',p_message)); IF req.status='succeeded' THEN RETURN req.result; END IF; BEGIN INSERT INTO public.festival_artist_invitations(festival_artist_programme_id,artist_type,artist_profile_id,band_id,invited_by_profile_id,status,message,suggested_fee_minor,suggested_set_minutes,suggested_dates,suggested_stage_types,expires_at) VALUES(pr.id,p_artist_type,p_artist_profile_id,p_band_id,a,'sent',p_message,p_suggested_fee_minor,p_suggested_set_minutes,p_suggested_dates,p_suggested_stage_types,p_response_deadline) RETURNING * INTO x; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'festival_artist_invitation_duplicate' USING ERRCODE='P0001'; END; PERFORM public._festival_artist_audit(p_festival_company_id,a,'invitation',x.id,'invitation_sent',NULL,'sent',1); IF p_artist_profile_id IS NOT NULL THEN PERFORM public._festival_artist_notify(req.id,p_artist_profile_id,'invitation_received','Festival invitation received','A Festival manager invited you to discuss a performance.'); END IF; RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','invitation','invitation',to_jsonb(x))); END $$;
CREATE OR REPLACE FUNCTION public.respond_to_festival_artist_invitation(p_invitation_id uuid,p_expected_version integer,p_response text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); x public.festival_artist_invitations%ROWTYPE; c uuid; req public.festival_artist_plan_requests%ROWTYPE; BEGIN SELECT i.* INTO x FROM public.festival_artist_invitations i WHERE i.id=p_invitation_id FOR UPDATE; SELECT festival_company_id INTO c FROM public.festival_artist_programmes WHERE id=x.festival_artist_programme_id; req:=public._festival_artist_begin(c,'respond_invitation','invitation',x.id,p_idempotency_key,jsonb_build_object('version',p_expected_version,'response',p_response)); IF req.status='succeeded' THEN RETURN req.result; END IF; IF NOT public._festival_artist_authorised(a,x.artist_type,x.artist_profile_id,x.band_id) THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; IF x.version<>p_expected_version THEN RAISE EXCEPTION 'festival_artist_offer_stale' USING ERRCODE='P0001'; END IF; IF x.status NOT IN ('sent','viewed') OR x.expires_at<=now() OR p_response NOT IN ('interested','declined') THEN RAISE EXCEPTION 'festival_artist_invitation_invalid_transition' USING ERRCODE='P0001'; END IF; UPDATE public.festival_artist_invitations SET status=p_response,responded_at=now(),version=version+1 WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_artist_audit(c,a,'invitation',x.id,'invitation_'||p_response,NULL,p_response,x.version); RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','invitation','invitation',to_jsonb(x))); END $$;

CREATE OR REPLACE FUNCTION public.create_festival_artist_offer(p_festival_company_id uuid,p_application_id uuid,p_invitation_id uuid,p_artist_type text,p_artist_profile_id uuid,p_band_id uuid,p_terms jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); pr public.festival_artist_programmes%ROWTYPE; x public.festival_artist_offers%ROWTYPE; req public.festival_artist_plan_requests%ROWTYPE; fee bigint:=coalesce((p_terms->>'feeMinor')::bigint,0); mins int:=coalesce((p_terms->>'setMinutes')::int,30); BEGIN IF NOT public._festival_artist_manager(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; SELECT * INTO pr FROM public.festival_artist_programmes WHERE festival_company_id=p_festival_company_id; req:=public._festival_artist_begin(p_festival_company_id,'create_offer','artist',coalesce(p_application_id,p_invitation_id,p_artist_profile_id,p_band_id),p_idempotency_key,jsonb_build_object('application',p_application_id,'invitation',p_invitation_id,'type',p_artist_type,'profile',p_artist_profile_id,'band',p_band_id,'terms',p_terms)); IF req.status='succeeded' THEN RETURN req.result; END IF; IF fee<0 OR mins NOT BETWEEN 10 AND 240 THEN RAISE EXCEPTION 'festival_artist_offer_invalid' USING ERRCODE='P0001'; END IF; INSERT INTO public.festival_artist_offers(festival_artist_programme_id,application_id,invitation_id,artist_type,artist_profile_id,band_id,offered_fee_minor,currency_code,set_minutes,performance_count,preferred_date,preferred_stage_id,billing_position,travel_support_minor,accommodation_support_minor,merch_revenue_share_basis_points,response_deadline,created_by_profile_id) VALUES(pr.id,p_application_id,p_invitation_id,p_artist_type,p_artist_profile_id,p_band_id,fee,pr.currency_code,mins,coalesce((p_terms->>'performanceCount')::int,1),(p_terms->>'preferredDate')::date,(p_terms->>'preferredStageId')::uuid,coalesce(p_terms->>'billingPosition','support'),coalesce((p_terms->>'travelSupportMinor')::bigint,0),coalesce((p_terms->>'accommodationSupportMinor')::bigint,0),coalesce((p_terms->>'merchShareBasisPoints')::int,0),(p_terms->>'responseDeadline')::timestamptz,a) RETURNING * INTO x; INSERT INTO public.festival_artist_offer_revisions(offer_id,offer_version,proposed_by_party,proposed_by_profile_id,fee_minor,set_minutes,preferred_date,preferred_stage_id,billing_position,travel_support_minor,accommodation_support_minor,merch_revenue_share_basis_points,terms_snapshot,message) VALUES(x.id,1,'festival',a,x.offered_fee_minor,x.set_minutes,x.preferred_date,x.preferred_stage_id,x.billing_position,x.travel_support_minor,x.accommodation_support_minor,x.merch_revenue_share_basis_points,p_terms,p_terms->>'message'); PERFORM public._festival_artist_audit(p_festival_company_id,a,'offer',x.id,'offer_created',NULL,'draft',1); RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','offer','offer',to_jsonb(x),'revisions',jsonb_build_array(p_terms))); END $$;
CREATE OR REPLACE FUNCTION public.send_festival_artist_offer(p_offer_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); x public.festival_artist_offers%ROWTYPE; c uuid; req public.festival_artist_plan_requests%ROWTYPE; committed bigint; budget bigint; BEGIN SELECT * INTO x FROM public.festival_artist_offers WHERE id=p_offer_id FOR UPDATE; SELECT pr.festival_company_id,pr.artist_budget_minor+pr.contingency_budget_minor INTO c,budget FROM public.festival_artist_programmes pr WHERE pr.id=x.festival_artist_programme_id; IF NOT public._festival_artist_manager(c,a) THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; req:=public._festival_artist_begin(c,'send_offer','offer',x.id,p_idempotency_key,jsonb_build_object('version',p_expected_version)); IF req.status='succeeded' THEN RETURN req.result; END IF; SELECT coalesce(sum(amount_minor),0) INTO committed FROM public.festival_financial_commitments fc WHERE fc.festival_company_id=c AND fc.status='committed'; IF x.offer_version<>p_expected_version THEN RAISE EXCEPTION 'festival_artist_offer_stale' USING ERRCODE='P0001'; END IF; IF x.status NOT IN ('draft','countered') OR x.response_deadline<=now() OR committed+x.offered_fee_minor+x.travel_support_minor+x.accommodation_support_minor>budget THEN RAISE EXCEPTION 'festival_artist_offer_budget_exceeded' USING ERRCODE='P0001'; END IF; UPDATE public.festival_artist_offers SET status='sent',updated_at=now() WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_artist_audit(c,a,'offer',x.id,'offer_sent',NULL,'sent',x.offer_version); IF x.artist_profile_id IS NOT NULL THEN PERFORM public._festival_artist_notify(req.id,x.artist_profile_id,'offer_received','Festival offer received','A contractual Festival offer is ready for your review.'); END IF; RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','offer','offer',to_jsonb(x))); END $$;
CREATE OR REPLACE FUNCTION public.counter_festival_artist_offer(p_offer_id uuid,p_expected_version integer,p_terms jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); x public.festival_artist_offers%ROWTYPE; c uuid; req public.festival_artist_plan_requests%ROWTYPE; nv int; BEGIN SELECT * INTO x FROM public.festival_artist_offers WHERE id=p_offer_id FOR UPDATE; SELECT festival_company_id INTO c FROM public.festival_artist_programmes WHERE id=x.festival_artist_programme_id; req:=public._festival_artist_begin(c,'counter_offer','offer',x.id,p_idempotency_key,jsonb_build_object('version',p_expected_version,'terms',p_terms)); IF req.status='succeeded' THEN RETURN req.result; END IF; IF NOT public._festival_artist_authorised(a,x.artist_type,x.artist_profile_id,x.band_id) THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; IF x.offer_version<>p_expected_version THEN RAISE EXCEPTION 'festival_artist_offer_stale' USING ERRCODE='P0001'; END IF; IF x.status<>'sent' OR x.response_deadline<=now() THEN RAISE EXCEPTION 'festival_artist_offer_invalid_transition' USING ERRCODE='P0001'; END IF; nv:=x.offer_version+1; UPDATE public.festival_artist_offers SET status='countered',offer_version=nv,offered_fee_minor=coalesce((p_terms->>'feeMinor')::bigint,offered_fee_minor),set_minutes=coalesce((p_terms->>'setMinutes')::int,set_minutes),travel_support_minor=coalesce((p_terms->>'travelSupportMinor')::bigint,travel_support_minor),accommodation_support_minor=coalesce((p_terms->>'accommodationSupportMinor')::bigint,accommodation_support_minor),updated_at=now() WHERE id=x.id RETURNING * INTO x; INSERT INTO public.festival_artist_offer_revisions(offer_id,offer_version,proposed_by_party,proposed_by_profile_id,fee_minor,set_minutes,preferred_date,preferred_stage_id,billing_position,travel_support_minor,accommodation_support_minor,merch_revenue_share_basis_points,terms_snapshot,message) VALUES(x.id,nv,'artist',a,x.offered_fee_minor,x.set_minutes,x.preferred_date,x.preferred_stage_id,x.billing_position,x.travel_support_minor,x.accommodation_support_minor,x.merch_revenue_share_basis_points,p_terms,p_terms->>'message'); PERFORM public._festival_artist_audit(c,a,'offer',x.id,'offer_countered','sent','countered',nv); RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','offer','offer',to_jsonb(x))); END $$;
CREATE OR REPLACE FUNCTION public.respond_to_festival_artist_offer(p_offer_id uuid,p_expected_version integer,p_response text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); x public.festival_artist_offers%ROWTYPE; pr public.festival_artist_programmes%ROWTYPE; req public.festival_artist_plan_requests%ROWTYPE; b public.festival_artist_bookings%ROWTYPE; fc public.festival_financial_commitments%ROWTYPE; total bigint; committed bigint; BEGIN SELECT * INTO x FROM public.festival_artist_offers WHERE id=p_offer_id FOR UPDATE; SELECT * INTO pr FROM public.festival_artist_programmes WHERE id=x.festival_artist_programme_id FOR UPDATE; req:=public._festival_artist_begin(pr.festival_company_id,'respond_offer','offer',x.id,p_idempotency_key,jsonb_build_object('version',p_expected_version,'response',p_response)); IF req.status='succeeded' THEN RETURN req.result; END IF; IF NOT public._festival_artist_authorised(a,x.artist_type,x.artist_profile_id,x.band_id) OR p_response NOT IN ('accept','decline') THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; IF x.offer_version<>p_expected_version THEN RAISE EXCEPTION 'festival_artist_offer_stale' USING ERRCODE='P0001'; END IF; IF x.status NOT IN ('sent','countered') OR x.response_deadline<=now() THEN RAISE EXCEPTION 'festival_artist_offer_invalid_transition' USING ERRCODE='P0001'; END IF; IF p_response='decline' THEN UPDATE public.festival_artist_offers SET status='declined',declined_at=now(),updated_at=now() WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_artist_audit(pr.festival_company_id,a,'offer',x.id,'offer_declined',NULL,'declined',x.offer_version); RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','offer','offer',to_jsonb(x))); END IF;
 total:=x.offered_fee_minor+x.travel_support_minor+x.accommodation_support_minor; SELECT coalesce(sum(amount_minor),0) INTO committed FROM public.festival_financial_commitments WHERE festival_company_id=pr.festival_company_id AND status='committed'; IF committed+total>pr.artist_budget_minor+pr.contingency_budget_minor THEN RAISE EXCEPTION 'festival_artist_offer_budget_exceeded' USING ERRCODE='P0001'; END IF;
 UPDATE public.festival_artist_offers SET status='accepted',accepted_at=now(),updated_at=now() WHERE id=x.id RETURNING * INTO x; UPDATE public.festival_artist_offer_revisions SET terms_snapshot=terms_snapshot||jsonb_build_object('acceptedAt',now()) WHERE offer_id=x.id AND offer_version=x.offer_version;
 INSERT INTO public.festival_artist_bookings(festival_artist_programme_id,offer_id,artist_type,artist_profile_id,band_id,npc_artist_id,agreed_fee_minor,travel_support_minor,accommodation_support_minor,total_commitment_minor,currency_code,set_minutes,performance_count,provisional_date,provisional_stage_id,billing_position,contract_terms) VALUES(x.festival_artist_programme_id,x.id,x.artist_type,x.artist_profile_id,x.band_id,x.npc_artist_id,x.offered_fee_minor,x.travel_support_minor,x.accommodation_support_minor,total,x.currency_code,x.set_minutes,x.performance_count,x.preferred_date,x.preferred_stage_id,x.billing_position,(SELECT terms_snapshot FROM public.festival_artist_offer_revisions WHERE offer_id=x.id AND offer_version=x.offer_version)) RETURNING * INTO b;
 INSERT INTO public.festival_financial_commitments(festival_company_id,artist_booking_id,amount_minor,currency_code) VALUES(pr.festival_company_id,b.id,total,x.currency_code) RETURNING * INTO fc; UPDATE public.festival_artist_applications SET status='accepted',updated_at=now(),version=version+1 WHERE id=x.application_id; UPDATE public.festival_artist_invitations SET status='converted_to_offer',version=version+1 WHERE id=x.invitation_id; PERFORM public._festival_artist_audit(pr.festival_company_id,a,'offer',x.id,'offer_accepted',NULL,'accepted',x.offer_version); PERFORM public._festival_artist_audit(pr.festival_company_id,a,'booking',b.id,'booking_confirmed',NULL,'awaiting_schedule',1); PERFORM public._festival_artist_notify(req.id,a,'booking_confirmed','Festival booking confirmed','The accepted terms are now a budget commitment; no payment has been transferred.'); RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','booking','programme',public._festival_artist_programme_result(pr.festival_company_id),'offer',to_jsonb(x),'booking',to_jsonb(b),'commitment',to_jsonb(fc)));
END $$;
CREATE OR REPLACE FUNCTION public.withdraw_festival_artist_offer(p_offer_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); x public.festival_artist_offers%ROWTYPE; c uuid; req public.festival_artist_plan_requests%ROWTYPE; BEGIN SELECT * INTO x FROM public.festival_artist_offers WHERE id=p_offer_id FOR UPDATE; SELECT festival_company_id INTO c FROM public.festival_artist_programmes WHERE id=x.festival_artist_programme_id; IF NOT public._festival_artist_manager(c,a) THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; req:=public._festival_artist_begin(c,'withdraw_offer','offer',x.id,p_idempotency_key,jsonb_build_object('version',p_expected_version)); IF req.status='succeeded' THEN RETURN req.result; END IF; IF x.offer_version<>p_expected_version THEN RAISE EXCEPTION 'festival_artist_offer_stale' USING ERRCODE='P0001'; END IF; IF x.status NOT IN ('draft','sent','countered') THEN RAISE EXCEPTION 'festival_artist_offer_invalid_transition' USING ERRCODE='P0001'; END IF; UPDATE public.festival_artist_offers SET status='withdrawn',cancelled_at=now(),updated_at=now() WHERE id=x.id RETURNING * INTO x; PERFORM public._festival_artist_audit(c,a,'offer',x.id,'offer_withdrawn',NULL,'withdrawn',x.offer_version); RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','offer','offer',to_jsonb(x))); END $$;
CREATE OR REPLACE FUNCTION public.cancel_festival_artist_booking(p_booking_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); b public.festival_artist_bookings%ROWTYPE; c uuid; req public.festival_artist_plan_requests%ROWTYPE; BEGIN SELECT * INTO b FROM public.festival_artist_bookings WHERE id=p_booking_id FOR UPDATE; SELECT festival_company_id INTO c FROM public.festival_artist_programmes WHERE id=b.festival_artist_programme_id; IF NOT public._festival_artist_manager(c,a) AND NOT public._festival_artist_authorised(a,b.artist_type,b.artist_profile_id,b.band_id) THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; req:=public._festival_artist_begin(c,'cancel_booking','booking',b.id,p_idempotency_key,jsonb_build_object('version',p_expected_version)); IF req.status='succeeded' THEN RETURN req.result; END IF; IF b.version<>p_expected_version THEN RAISE EXCEPTION 'festival_artist_offer_stale' USING ERRCODE='P0001'; END IF; IF b.status NOT IN ('awaiting_schedule','confirmed') THEN RAISE EXCEPTION 'festival_artist_booking_invalid_transition' USING ERRCODE='P0001'; END IF; UPDATE public.festival_artist_bookings SET status=CASE WHEN public._festival_artist_manager(c,a) THEN 'festival_cancelled' ELSE 'artist_withdrawn' END,cancelled_at=now(),updated_at=now(),version=version+1 WHERE id=b.id RETURNING * INTO b; UPDATE public.festival_financial_commitments SET status='released',released_at=now() WHERE artist_booking_id=b.id AND status='committed'; PERFORM public._festival_artist_audit(c,a,'booking',b.id,'booking_cancelled',NULL,b.status,b.version); RETURN public._festival_artist_finish(req.id,jsonb_build_object('kind','booking','booking',to_jsonb(b))); END $$;
CREATE OR REPLACE FUNCTION public.get_my_festival_artist_opportunities() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; RETURN jsonb_build_object('openApplications',coalesce((SELECT jsonb_agg(jsonb_build_object('windowId',w.id,'festivalCompanyId',pr.festival_company_id,'name',w.name,'opensAt',w.opens_at,'closesAt',w.closes_at,'eligibleArtistType',w.eligible_artist_type,'minimumFame',w.minimum_fame,'maximumFame',w.maximum_fame,'preferredGenres',w.preferred_genres,'stageTypes',w.target_stage_types,'canApply',true)) FROM public.festival_artist_application_windows w JOIN public.festival_artist_programmes pr ON pr.id=w.festival_artist_programme_id WHERE w.active AND now() BETWEEN w.opens_at AND w.closes_at AND pr.application_mode IN ('applications_only','hybrid')),'[]'),'applications',coalesce((SELECT jsonb_agg(to_jsonb(x)-'availability_snapshot') FROM public.festival_artist_applications x WHERE x.artist_profile_id=a OR public._festival_artist_authorised(a,x.artist_type,x.artist_profile_id,x.band_id)),'[]'),'invitations',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_artist_invitations x WHERE x.artist_profile_id=a OR public._festival_artist_authorised(a,x.artist_type,x.artist_profile_id,x.band_id)),'[]'),'offers',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('revisions',coalesce((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.offer_version) FROM public.festival_artist_offer_revisions r WHERE r.offer_id=x.id),'[]'))) FROM public.festival_artist_offers x WHERE x.artist_profile_id=a OR public._festival_artist_authorised(a,x.artist_type,x.artist_profile_id,x.band_id)),'[]'),'bookings',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_artist_bookings x WHERE x.artist_profile_id=a OR public._festival_artist_authorised(a,x.artist_type,x.artist_profile_id,x.band_id)),'[]'),'permissions',jsonb_build_object('profileId',a,'canApplySolo',true,'managedBandIds',coalesce((SELECT jsonb_agg(bm.band_id) FROM public.band_members bm WHERE bm.profile_id=a AND coalesce(bm.member_status,'active')='active' AND lower(coalesce(bm.role,'')) IN ('leader','founder','co-leader','manager')),'[]'))); END $$;
CREATE OR REPLACE FUNCTION public.search_festival_artist_candidates(p_festival_company_id uuid,p_query text DEFAULT NULL,p_artist_type text DEFAULT NULL,p_genres text[] DEFAULT '{}',p_minimum_fame integer DEFAULT NULL,p_maximum_fame integer DEFAULT NULL,p_player_npc text DEFAULT NULL,p_availability text DEFAULT NULL,p_stage_type text DEFAULT NULL,p_limit integer DEFAULT 25,p_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id(); BEGIN IF NOT public._festival_artist_manager(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_artist_action_forbidden' USING ERRCODE='P0001'; END IF; RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(jsonb_build_object('identity',jsonb_build_object('type','solo','artistProfileId',p.id),'displayName',coalesce(p.display_name,p.username),'playerNpc','player','genres','[]'::jsonb,'fame',coalesce(p.fame,0),'popularity',0,'homeCity',NULL,'estimatedFeeMinimumMinor',greatest(0,coalesce(p.fame,0)*100),'estimatedFeeMaximumMinor',greatest(10000,coalesce(p.fame,0)*250),'availabilityState','unknown','stageSuitability',0,'genreFit',0,'audienceFit',least(100,coalesce(p.fame,0)),'relationshipState','none')) FROM (SELECT * FROM public.profiles WHERE (p_query IS NULL OR display_name ILIKE '%'||p_query||'%' OR username ILIKE '%'||p_query||'%') AND (p_minimum_fame IS NULL OR fame>=p_minimum_fame) AND (p_maximum_fame IS NULL OR fame<=p_maximum_fame) ORDER BY fame DESC,id LIMIT least(greatest(p_limit,1),50) OFFSET greatest(p_offset,0)) p),'[]'),'limit',least(greatest(p_limit,1),50),'offset',greatest(p_offset,0)); END $$;

REVOKE ALL ON FUNCTION public._festival_artist_authorised(uuid,text,uuid,uuid),public._festival_artist_begin(uuid,text,text,uuid,uuid,jsonb),public._festival_artist_finish(uuid,jsonb),public._festival_artist_audit(uuid,uuid,text,uuid,text,text,text,integer),public._festival_artist_notify(uuid,uuid,text,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.submit_festival_artist_application(uuid,uuid,text,uuid,uuid,date[],text[],bigint,bigint,integer,integer,text,uuid),public.withdraw_festival_artist_application(uuid,integer,uuid),public.review_festival_artist_application(uuid,uuid,integer,text,text,uuid),public.send_festival_artist_invitation(uuid,text,uuid,uuid,bigint,integer,date[],text[],timestamptz,text,uuid),public.respond_to_festival_artist_invitation(uuid,integer,text,uuid),public.create_festival_artist_offer(uuid,uuid,uuid,text,uuid,uuid,jsonb,uuid),public.send_festival_artist_offer(uuid,integer,uuid),public.counter_festival_artist_offer(uuid,integer,jsonb,uuid),public.respond_to_festival_artist_offer(uuid,integer,text,uuid),public.withdraw_festival_artist_offer(uuid,integer,uuid),public.cancel_festival_artist_booking(uuid,integer,uuid),public.get_my_festival_artist_opportunities(),public.search_festival_artist_candidates(uuid,text,text,text[],integer,integer,text,text,text,integer,integer) TO authenticated;
